            if not matches(state['stage'],target):states[name]='unapproved';continue
            try:node['exchange']()
            except Exception:pass
            actual=node['inspect']()
            states[name]='ready' if actual['engine']=='Atomic' and matches(actual['catalog'],target) else 'inconsistent'
        except Exception:states[name]='unreachable'
    admitted=sorted(name for name,status in states.items() if status=='ready')
    return {'completed':len(admitted)==len(nodes),'admitted':admitted,'states':states}
