import http.server,json,os,pathlib,secrets,shutil,subprocess,threading,time,urllib.request
from ch_server import Server

class Restartable(Server):
 def stop(self):
  if self.process.poll() is None:
   self.process.terminate();self.process.wait(timeout=4)
 def restart(self):
  assert self.process.poll() is not None
  self.process=subprocess.Popen([shutil.which('clickhouse'),'server','--config-file='+str(self.config_path)],cwd=self.root,stdout=self.log,stderr=self.log,env={**os.environ,'HOME':str(self.root),'TMPDIR':str(self.root)})
  deadline=time.monotonic()+15
  while time.monotonic()<deadline:
   try:
    if self.query('SELECT 1 AS ready')==[{'ready':1}]:return
   except Exception:pass
   if self.process.poll() is not None:raise AssertionError('owned ClickHouse restart exited')
   time.sleep(.05)
  raise AssertionError('owned ClickHouse restart timed out')

class LostAck:
