 def __enter__(self):
  owner=self
  class Handler(http.server.BaseHTTPRequestHandler):
   def log_message(self,*args):pass
   def do_POST(self):
    sql=self.rfile.read(int(self.headers['Content-Length'])).decode()
    assert sql=='EXCHANGE TABLES shop.catalog AND shop.catalog_stage'
    owner.server.execute(sql);owner.applied+=1;owner.pending.set()
    time.sleep(.8)
    try:self.send_response(200);self.send_header('Content-Length','0');self.end_headers()
    except (BrokenPipeError,ConnectionResetError):pass
  self.http=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler)
  self.thread=threading.Thread(target=self.http.serve_forever,daemon=True);self.thread.start();return self
 def exchange(self):
  if self.applied:
   self.server.execute('EXCHANGE TABLES shop.catalog AND shop.catalog_stage');self.applied+=1;return
  request=urllib.request.Request('http://127.0.0.1:'+str(self.http.server_port)+'/',data=b'EXCHANGE TABLES shop.catalog AND shop.catalog_stage',method='POST')
  try:
   with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(request,timeout=.2) as response:response.read()
  except TimeoutError:
   assert self.pending.is_set(),'DDL was not applied before timeout';self.timed_out=True;raise
 def __exit__(self,*args):
  self.http.shutdown();self.http.server_close();self.thread.join(timeout=3)
  assert not self.thread.is_alive()

